{
  "name": "ke_state_machine_step_if_ready",
  "confidence": "medium",
  "docstring": "When the parent kernel context is enabled and unblocked, clear pending event-lock flags in the selected 140-byte state-machine entry and advance the state machine.",
  "subsystem": "ke",
  "var_renames": {
    "v2": "state_index",
    "v3": "state_machine_base",
    "v4": "state_machine",
    "v5": "state_machine_offset",
    "v8": "pending_event_flag"
  },
  "struct_hints": [
    {
      "offset": 106,
      "meaning": "parent-context flag that blocks state-machine stepping when nonzero"
    },
    {
      "offset": 1224,
      "meaning": "parent-context state-machine enable flag"
    },
    {
      "offset": 1225,
      "meaning": "parent-context selected state-machine index"
    },
    {
      "offset": 0,
      "meaning": "first event-lock header in the 140-byte state-machine entry"
    },
    {
      "offset": 16,
      "meaning": "first pending event flag cleared under the lock at entry offset 0"
    },
    {
      "offset": 48,
      "meaning": "second event-lock header in the 140-byte state-machine entry"
    },
    {
      "offset": 64,
      "meaning": "second pending event flag cleared under the lock at entry offset 48"
    },
    {
      "offset": 96,
      "meaning": "third event-lock header in the 140-byte state-machine entry"
    },
    {
      "offset": 114,
      "meaning": "third pending event flag cleared under the lock at entry offset 96"
    }
  ]
}
